  html4: v => `<!DOCTYPE html>\n<html>\n<head>\n  <title>${v.place}</title>\n</head>\n<body>\n  <h1>${v.hero}'s checklist</h1>\n  <ul>\n    <li>Collect ${v.item}</li>\n    <li>Beat the level</li>\n    <li>Share with friends</li>\n  </ul>\n  <button>Start</button>\n</body>\n</html>\n`,
  html5: v => `<!DOCTYPE html>\n<html>\n<head>\n  <title>${v.place}</title>\n  <style>\n    body {\n      background: #ffe066;\n      text-align: center;\n    }\n    h1 {\n      color: #ff3d7f;\n      font-size: 40px;\n    }\n  </style>\n</head>\n<body>\n  <h1>${v.place}</h1>\n  <p>Change the colors and see what happens!</p>\n</body>\n</html>\n`,
